\begin{tikzpicture}[font=\sffamily, scale=1]

  % Boundary of magnetic field region
  \draw[thick] (0, -2.5) rectangle (6, 2.5);

  % Magnetic field crosses (into the page)
  \foreach \x in {0.8, 1.8, ..., 5.8} {
    \foreach \y in {-2.0, -1.0, 0.0, 1.0, 2.0} {
      \node[circle, inner sep=1pt, minimum size=2pt] at (\x, \y) {$\times$};
    }
  }

  % Semicircular path of electron inside the field (from 0,0 to 0,4 radius 2 centered at (0,2))
  % Let's center the semicircle of radius r at (3,0) going from bottom edge to top edge.
  % Entry point: (0, 0)
  % Exit point: (0, 4) -> wait, let's keep it entirely inside the 0 to 6 width.
  % Let entry be at (1, -2) and exit at (1, 2) with radius 2, center at (3, 0).
  % Let's adjust:
  % Boundary left edge at x = 2.
  % Entry at (2, -2), exit at (2, 2). Radius r = 2, Center at (4, 0).

  \coordinate (C) at (4,0);
  \coordinate (Entry) at (2,-2);
  \coordinate (Exit) at (2,2);

  % Electron path (semicircle)
  \draw[thick, postaction={decorate, decoration={markings, mark=at position 0.5 with {\arrow{latex}}}}] 
    (Entry) arc[start angle=-90, end angle=90, radius=2];

  % Incoming path (outside field)
  \draw[thick, -{latex}] (0,-2) -- (Entry);

  % Outgoing path (outside field)
  \draw[thick, -{latex}] (Exit) -- (0,2);

  % Labels for electron and paths
  \node[above] at (0.5,-2) {electron};
  \node[above left] at (Entry) {$e^-$};

  % Radius r and center C
  \draw[dashed] (C) -- node[above] {$r$} (Exit);
  \fill (C) circle (1.5pt) node[below right] {C};

  % Field region label
  \node[anchor=south west] at (2, 2.5) {Region of uniform magnetic field};
  \node[anchor=north west] at (2, 2.5) {(directed into page)};

  % Caption
  \node at (3, -3.2) {Fig. 3.1};

\end{tikzpicture}
